\label{def:B}
Let $\mathcal A$ be the real vector space with ordered basis $\{\mathbf 1,i,j\}$.  Define a
bilinear multiplication by the table
\begin{equation}\label{eq:table}
\begin{array}{c|ccc}
     &\mathbf 1&i&j\\ \hline
\mathbf 1 &\mathbf 1&i&j\\
i    &i&-\mathbf 1&0\\
j    &j&i+j&-\mathbf 1
\end{array}.
\end{equation}
Equivalently, after identifying $a\mathbf 1+bi+cj$ with $(a,b,c)$,
\begin{equation}\label{eq:product}
(a,b,c)(d,e,f)
=\bigl(ad-be-cf,\;ae+bd+ce,\;af+ce+cd\bigr).
\end{equation}

\label{prop:associator}
For
\[
x=(a,b,c),\qquad y=(d,e,f),\qquad z=(g,h,r),
\]
the associator is
\begin{equation}\label{eq:associator}
(x,y,z)=
\begin{pmatrix}
bfh-ceh-cer+cfh\\
bfr+ceh-2cfh\\
-ber+2ceh-cfh
\end{pmatrix}.
\end{equation}
In particular,
\begin{equation}\label{eq:third-power}
(x,x,x)=bc(b-c)(i+j).
\end{equation}

\label{cor:identity-failures}
The algebra $\mathcal A$ is noncommutative, nonassociative, nonalternative,
nonflexible, and not power-associative.

\label{thm:slices}
Each of $\mathbb C_i,\mathbb C_j,\mathbb C_k$ is an associative unital subalgebra isomorphic to
$\mathbb C$.  They are precisely the two-dimensional subalgebras of $\mathcal A$ that
contain $\mathbf 1$.  Moreover, for $x=(a,b,c)$ the following are equivalent:
\begin{enumerate}
\item the subalgebra generated by $\mathbf 1$ and $x$ is associative;
\item all powers of $x$ are independent of parenthesization;
\item $(x,x,x)=0$;
\item $bc(b-c)=0$;
\item $x\in\mathbb C_i\cup\mathbb C_j\cup\mathbb C_k$;
\item $x$ is quadratic.
\end{enumerate}

\label{prop:zero-divisors}
For $x=(a,b,c)$, there exists $0\neq y$ with $xy=0$ if and only if
\begin{equation}\label{eq:delta-L}
\Delta_L(x):=a^3+a^2c+a(b^2+c^2)-bc^2+c^3=0.
\end{equation}
There exists $0\neq y$ with $yx=0$ if and only if
\begin{equation}\label{eq:delta-R}
\Delta_R(x):=a^3+a^2b+a(b^2+c^2)+b^3-b^2c=0.
\end{equation}

\label{prop:quadratic}
The only idempotents of $\mathcal A$ are $0$ and $\mathbf 1$.  The only solution of
$x^2=0$ is $x=0$.

\label{prop:roots-minus-one}
The equation $x^2=-\mathbf 1$ has exactly six real solutions:
\begin{equation}\label{eq:roots-minus-one}
\mathcal S=\left\{\pm i,\ \pm j,\
\ \pm\frac{\mathbf 1-2i-2j}{\sqrt7}\right\}.
\end{equation}

\label{prop:other-identities}
The associator is neither left-symmetric nor right-symmetric, and $\mathcal A$ is
not Jordan-admissible.
